// Writes shell.html (issue #91): an invented app screen at the scale and shape of a real one, about 100 KB, with an app
// shell, a sidebar, a tablist, a toolbar, 100 order rows, and the nested wrappers a component library leaves.
// Run: node test/fixtures/realistic/make-shell.ts
import { writeFileSync } from "node:fs";

const wrap = (depth: number, inner: string) =>
  Array.from({ length: depth }).reduce<string>((html, _, i) => `<div class="w${i}">${html}</div>`, inner);
const CUSTOMERS = [
  "Harbor Bakery",
  "Lumen Labs",
  "Orchid Florals",
  "Pinecrest Hardware",
  "Quarry Coffee",
  "Ridge Cycles",
];
const STATUSES = ["Pending", "Packed", "Shipped", "Delivered", "On hold"];
const OWNERS = ["Mira Holt", "Theo Vance", "Ines Park", "Arlo Brandt"];
const rows = Array.from({ length: 100 }, (_, i) => {
  const n = 4100 + i;
  const customer = CUSTOMERS[i % CUSTOMERS.length];
  const cells = [
    `<span class="id">#${n}</span>`,
    `<span class="customer">${customer}</span>`,
    `<span class="badge">${STATUSES[(i * 7) % STATUSES.length]}</span>`,
    `<span class="owner">${OWNERS[(i * 3) % OWNERS.length]}</span>`,
    `<span class="items">${(i % 9) + 1} items</span>`,
    `<span class="total">${(i * 37) % 900}.${String((i * 13) % 100).padStart(2, "0")} EUR</span>`,
  ]
    .map((c) => wrap(4, c))
    .join("");
  const actions = wrap(2, `<button type="button">Open</button><button type="button">Archive</button>`);
  return `<li class="order">${wrap(2, `<div class="cells">${cells}</div>${actions}`)}</li>`;
}).join("\n");
const nav = ["Dashboard", "Orders", "Customers", "Inventory", "Shipments", "Invoices", "Reports", "Integrations"]
  .map((l) => `<li>${wrap(2, `<a href="#${l.toLowerCase()}">${l}</a>`)}</li>`)
  .join("");
const filters = ["All", "Pending", "Packed", "Shipped", "Delivered", "On hold"]
  .map((f) => wrap(2, `<label><input type="checkbox" ${f === "All" ? "checked" : ""}> ${f}</label>`))
  .join("");

writeFileSync(
  new URL("shell.html", import.meta.url),
  `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>Fernwood Ops</title>
<style>.order .cells{display:flex;gap:8px}.w0,.w1,.w2{display:contents}</style></head>
<!-- Generated by make-shell.ts (issue #91): an invented operations app screen. "Save view" shows a short note in the
     toolbar; nothing on the screen names an area for it, so a check with no named area must read the whole page. -->
<body>
${wrap(
  3,
  `<header>${wrap(2, `<span>Fernwood Ops</span><input type="search" aria-label="Search everything" placeholder="Search"><button type="button">Help</button><button type="button" aria-label="Account">MH</button>`)}</header>
<div class="layout">${wrap(
    2,
    `<nav aria-label="Sidebar"><ul>${nav}</ul></nav>
<main>${wrap(
      2,
      `<h1>Orders</h1>
<div role="tablist">${["Open", "Returns", "Drafts", "Archived"].map((t, i) => `<button role="tab" aria-selected="${i === 0}">${t}</button>`).join("")}</div>
<div role="toolbar" aria-label="Order tools">${wrap(2, `<button type="button" id="save">Save view</button><button type="button">Export</button><button type="button">Refresh</button><span id="note"></span>`)}</div>
<div role="group" aria-label="Status filters">${filters}</div>
<ul class="orders">
${rows}
</ul>`,
    )}</main>`,
  )}</div>`,
)}
<script>
document.getElementById("save").onclick = () => setTimeout(() => (document.getElementById("note").textContent = "View saved"), 200);
</script>
</body>
</html>
`,
);
